		"PostToolUse":[{"matcher":null,"hooks":[{"type":"command","command":"entire hooks codex post-tool-use","timeout":30}]}]
	}}`
	repoRoot, _ := writeTrustFixture(t, hooksJSON)
	require.Empty(t, MissingEntireHooks(repoRoot))
}

